   164	  <script src="site-shell.js"></script>
   165	  <script>
   166	    (function () {
   167	      var form = document.getElementById('recruitmentLeadForm');
   168	      var preview = document.getElementById('requestPreview');
   169	      var result = document.getElementById('requestResult');
   170	      var requestIdText = document.getElementById('requestIdText');
   171	      var downloadBtn = document.getElementById('downloadBriefBtn');
   172	      var downloadBtnInline = document.getElementById('downloadBriefBtnInline');
   173	      var copyBtn = document.getElementById('copyBriefBtn');
   174	      var resultStatus = document.getElementById('requestResultStatus');
   175	      var zaloUrl = 'https://zalo.me/0777315188';
   176	      var lastPayload = null;
   177	
   178	      function value(id) {
   179	        var el = document.getElementById(id);
   180	        return el ? String(el.value || '').trim() : '';
   181	      }
   182	
   183	      function buildPayload() {
   184	        var timestamp = new Date();
   185	        var createdAt = timestamp.toISOString().slice(0, 19);
   186	        var requestId = 'brief-' + createdAt.replace(/[:T]/g, '-');
   187	        return {
   188	          requestId: requestId,
   189	          companyName: value('companyName'),
   190	          contactName: value('contactName'),
   191	          contactPhone: value('contactPhone'),
   192	          contactEmail: value('contactEmail'),
   193	          jobTitle: value('jobTitle'),
   194	          jobLocation: value('jobLocation'),
   195	          jobQuantity: value('jobQuantity') || '1',
   196	          jobDeadline: value('jobDeadline'),
   197	          employmentType: value('employmentType'),
   198	          workMode: value('workMode'),
   199	          applicationMethod: value('applicationMethod'),
   200	          applicationContact: value('applicationContact'),
   201	          salaryLabel: value('salaryLabel'),
   202	          experienceLevel: value('experienceLevel'),
   203	          jobNotes: value('jobNotes'),
   204	          sourcePage: 'dang-tin-tuyen-dung.html',
   205	          sourceChannel: 'website-brief',
   206	          createdAt: createdAt
   207	        };
   208	      }
   209	
   210	      function formatRequestCode(requestId) {
   211	        return String(requestId || '').replace(/^brief-/, 'YC-');
   212	      }
   213	
   214	      function buildDownloadName(requestId) {
   215	        return 'yeu-cau-tuyen-dung-' + formatRequestCode(requestId).toLowerCase() + '.txt';
   216	      }
   217	
   218	      function buildBrief(payload) {
   219	        return [
   220	          'Thông tin tuyển dụng gửi Diệu Tâm',
   221	          'Mã tham chiếu: ' + formatRequestCode(payload.requestId),
   222	          'Công ty: ' + payload.companyName,
   223	          'Người liên hệ: ' + payload.contactName,
   224	          'SĐT/Zalo: ' + payload.contactPhone,
   225	          'Email: ' + (payload.contactEmail || 'Chưa cung cấp'),
   226	          'Vị trí cần tuyển: ' + payload.jobTitle,
   227	          'Khu vực làm việc: ' + payload.jobLocation,
   228	          'Số lượng: ' + (payload.jobQuantity || '1'),
   229	          'Hạn nhận hồ sơ: ' + (payload.jobDeadline || 'Chưa chốt'),
   230	          'Hình thức: ' + payload.employmentType,
   231	          'Cách làm việc: ' + payload.workMode,
   232	          'Cách nhận hồ sơ: ' + (payload.applicationMethod || 'Chưa ghi rõ'),
   233	          'Email / link nhận hồ sơ: ' + (payload.applicationContact || 'Chưa cung cấp'),
   234	          'Lương tham khảo: ' + (payload.salaryLabel || 'Chưa công khai'),
   235	          'Yêu cầu kinh nghiệm: ' + (payload.experienceLevel || 'Chưa ghi rõ'),
   236	          'Ghi chú thêm: ' + (payload.jobNotes || 'Không có ghi chú thêm')
   237	        ].join('\\n');
   238	      }
   239	
   240	      function ensureValidForm() {
   241	        if (!form) return false;
   242	        if (typeof form.reportValidity === 'function') {
   243	          return form.reportValidity();
   244	        }
   245	        return true;
   246	      }
   247	
   248	      function renderResult(payload, note) {
   249	        var brief = buildBrief(payload);
   250	        lastPayload = payload;
   251	        preview.textContent = brief;
   252	        if (requestIdText) {
   253	          requestIdText.textContent = formatRequestCode(payload.requestId);
   254	        }
   255	        if (resultStatus) {
   256	          resultStatus.textContent = note || 'Nội dung đã sẵn sàng. Bạn có thể sao chép hoặc mở Zalo để gửi.';
   257	        }
   258	        result.hidden = false;
   259	        result.scrollIntoView({ behavior: 'smooth', block: 'start' });
   260	        return brief;
   261	      }
   262	
   263	      function downloadBrief(payload) {
   264	        var blob = new Blob([buildBrief(payload)], { type: 'text/plain;charset=utf-8' });
   265	        var href = URL.createObjectURL(blob);
   266	        var anchor = document.createElement('a');
   267	        anchor.href = href;
   268	        anchor.download = buildDownloadName(payload.requestId);
   269	        document.body.appendChild(anchor);
   270	        anchor.click();
   271	        anchor.remove();
   272	        URL.revokeObjectURL(href);
   273	      }
   274	
   275	      function submitBrief(event) {
   276	        event.preventDefault();
   277	        if (!ensureValidForm()) return;
   278	        var payload = buildPayload();
   279	        renderResult(payload, 'Nội dung đã tạo xong. Bạn có thể sao chép, tải file hoặc mở Zalo để gửi.');
   280	      }
   281	
   282	      function handleDownload() {
   283	        if (!ensureValidForm()) return;
   284	        var payload = lastPayload || buildPayload();
   285	        downloadBrief(payload);
   286	        renderResult(payload, 'Đã tạo và tải file nội dung. Bạn có thể tiếp tục sao chép hoặc mở Zalo để gửi.');
   287	      }
   288	
   289	      function handleCopy() {
   290	        if (!ensureValidForm()) return;
   291	        var payload = lastPayload || buildPayload();
   292	        var brief = renderResult(payload, 'Đang chuẩn bị nội dung để sao chép...');
   293	        if (navigator.clipboard && navigator.clipboard.writeText) {
   294	          navigator.clipboard.writeText(brief).then(function () {
   295	            if (resultStatus) {
   296	              resultStatus.textContent = 'Đã sao chép nội dung. Bạn có thể mở Zalo và dán ngay.';
   297	            }
   298	          }).catch(function () {
   299	            if (resultStatus) {
   300	              resultStatus.textContent = 'Không thể sao chép tự động. Bạn có thể bôi đen phần nội dung bên dưới để sao chép thủ công.';
   301	            }
   302	          });
   303	          return;
   304	        }
   305	        if (resultStatus) {
   306	          resultStatus.textContent = 'Trình duyệt này không hỗ trợ sao chép tự động. Bạn có thể bôi đen phần nội dung bên dưới để sao chép thủ công.';
   307	        }
   308	      }
   309	
   310	      if (form) {
   311	        form.addEventListener('submit', submitBrief);
   312	      }
   313	      if (downloadBtn) {
   314	        downloadBtn.addEventListener('click', handleDownload);
   315	      }
   316	      if (downloadBtnInline) {
   317	        downloadBtnInline.addEventListener('click', handleDownload);
   318	      }
   319	      if (copyBtn) {
   320	        copyBtn.addEventListener('click', handleCopy);
   321	      }
   322	    })();
   323	  </script>
